#!/usr/bin/env bash
#
# KAGE-MAN.DOJO :: scripts/smoke-test.sh
#
# Verify that every lab container answers on its expected port, tested from a
# temporary container attached to the same macvlan segment (simulating what a
# student's Kali VM would see).
#
# The endpoint list is generated by scripts/gen-labs.sh into ./smoke.tests.
#
# Usage: ./scripts/smoke-test.sh [lab-filter ...]
#
set -o pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"

smokefile="$ROOT/smoke.tests"
[[ -f "$smokefile" ]] || { echo "error: smoke.tests not found - run ./scripts/gen-labs.sh first" >&2; exit 1; }

# lab | docker network | ip | port | check (tcp|http)
TESTS=()
while IFS= read -r line; do
  [[ -z "$line" || "$line" == \#* ]] && continue
  TESTS+=("$line")
done < "$smokefile"

filters=("$@")
pass=0; fail=0; fail_list=()

for t in "${TESTS[@]}"; do
  lab=$(cut -d'|' -f1 <<<"$t" | xargs)
  net=$(cut -d'|' -f2 <<<"$t" | xargs)
  ip=$(cut -d'|' -f3 <<<"$t" | xargs)
  port=$(cut -d'|' -f4 <<<"$t" | xargs)
  check=$(cut -d'|' -f5 <<<"$t" | xargs)

  if [[ -n "${EXCLUDE:-}" && "$lab" == *"$EXCLUDE"* ]]; then continue; fi

  if (( ${#filters[@]} )); then
    skip=1
    for flt in "${filters[@]}"; do
      [[ "$lab" == *"$flt"* ]] && { skip=0; break; }
    done
    (( skip )) && continue
  fi

  case "$check" in
    http) remote="wget -q -T 8 -O /dev/null http://$ip:$port/; rc=\$?; [ \$rc -eq 0 ] || [ \$rc -eq 8 ] && echo ok || echo fail" ;;
    tcp)  remote="nc -w 3 $ip $port </dev/null >/dev/null 2>&1 && echo ok || echo fail" ;;
    udp)  remote="apk add -q nmap >/dev/null 2>&1; nmap -sU -p $port -Pn --max-retries 2 $ip 2>/dev/null | grep -qE '$port/udp[[:space:]]+open' && echo ok || echo fail" ;;
    *)    echo "unknown check '$check'"; continue ;;
  esac

  res=$(docker run --rm --net "$net" alpine sh -c "$remote" 2>/dev/null | tail -1)
  if [[ "$res" == "ok" ]]; then
    printf '\033[1;32m[PASS]\033[0m %-20s %s:%s (%s)\n' "$lab" "$ip" "$port" "$check"
    pass=$((pass+1))
  else
    printf '\033[1;31m[FAIL]\033[0m %-20s %s:%s (%s)\n' "$lab" "$ip" "$port" "$check"
    fail=$((fail+1)); fail_list+=("$lab")
  fi
done

printf '\n%d passed, %d failed' "$pass" "$fail"
(( fail )) && printf ' -> %s' "${fail_list[*]}"
printf '\n'
(( fail == 0 ))
